import '../../../shared/repositories/repositories.dart'; import '../../domain/entities.dart'; import '../database/daos/organization_dao.dart'; import '../database/mappers/organization_mappers.dart';
final class LocalOrganizationRepository implements OrganizationRepository { const LocalOrganizationRepository(this.dao); final OrganizationDao dao; @override Future<List<Department>> getDepartments() async=>(await dao.getDepartments()).map((e)=>e.toDomain()).toList(); @override Future<Department?> getDepartmentById(String id) async=>(await dao.getDepartmentById(id))?.toDomain(); @override Future<List<Department>> getChildDepartments(String id) async=>(await dao.getChildDepartments(id)).map((e)=>e.toDomain()).toList(); @override Future<List<Team>> getTeams() async=>(await dao.getTeams()).map((e)=>e.toDomain()).toList(); @override Future<List<Team>> getTeamsByDepartment(String id) async=>(await dao.getTeamsByDepartment(id)).map((e)=>e.toDomain()).toList(); @override Future<List<TeamMembership>> getTeamMembers(String id) async=>(await dao.getTeamMembers(id)).map((e)=>e.toDomain()).toList(); }
